-- Strictly additive: zero destructive DDL, safe on existing Production & Cloud Dev D1 databases.

CREATE TABLE IF NOT EXISTS `public_challenges` (
	`id` text PRIMARY KEY NOT NULL,
	`slug` text NOT NULL UNIQUE,
	`title_key` text NOT NULL,
	`category` text NOT NULL,
	`metric_type` text NOT NULL,
	`target_value` real NOT NULL,
	`duration_days` integer NOT NULL,
	`start_date` text NOT NULL,
	`end_date` text NOT NULL,
	`tracks_json` text NOT NULL,
	`clinical_safe_for_json` text NOT NULL,
	`badge_id` text,
	`is_seasonal` integer DEFAULT 0 NOT NULL,
	`created_at` text NOT NULL
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS `challenge_participations` (
	`user_id` text NOT NULL,
	`challenge_id` text NOT NULL,
	`joined_at` text NOT NULL,
	`completed_at` text,
	`progress_value` real DEFAULT 0 NOT NULL,
	`progress_pct` integer DEFAULT 0 NOT NULL,
	`is_pinned` integer DEFAULT 0 NOT NULL,
	`updated_at` text NOT NULL,
	PRIMARY KEY(`user_id`, `challenge_id`)
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `idx_challenge_part_challenge` ON `challenge_participations` (`challenge_id`, `progress_pct` DESC);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS `friend_challenges` (
	`id` text PRIMARY KEY NOT NULL,
	`creator_user_id` text NOT NULL,
	`invite_code` text NOT NULL UNIQUE,
	`title` text NOT NULL,
	`metric_type` text NOT NULL,
	`duration_days` integer NOT NULL,
	`start_date` text NOT NULL,
	`end_date` text NOT NULL,
	`max_members` integer DEFAULT 12 NOT NULL,
	`status` text DEFAULT 'active' NOT NULL,
	`created_at` text NOT NULL
);
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS `idx_friend_challenges_creator` ON `friend_challenges` (`creator_user_id`, `status`);
--> statement-breakpoint
